# ------------------------------------------------------------------ line codes
LINECODES = [
    ("nrz", "NRZ-L", "1 = one level, 0 = the other, for the whole bit time.",
     "UART, RS-232 (inverted), RS-485, CAN (with bit stuffing), I2C, SPI"),
    ("nrzi", "NRZI", "0 = toggle at the start of the bit, 1 = no change (USB convention).",
     "USB (stuffed 0 after six 1s); 100BASE-FX / FDDI: 1 = toggle"),
    ("man", "Manchester (IEEE 802.3)", "Transition in the middle of every bit: 1 = low-to-high, 0 = high-to-low.",
     "10BASE-T Ethernet; self-clocking and DC-free, twice the bandwidth"),
    ("man2", "Manchester II bi-phase-L", "Middle transition: 1 = high-to-low (positive half first), 0 = low-to-high.",
     "MIL-STD-1553 (Manchester II bi-phase level)"),
    ("dman", "Differential Manchester", "Always a middle transition; a 0 adds a transition at the start of the bit, a 1 does not.",
     "Token Ring, LonWorks FT-10; polarity-insensitive"),
    ("bpm", "Biphase mark (FM1)", "Always a transition at the start of the bit; a 1 adds one in the middle.",
     "ARINC 717 (Harvard bi-phase), AES3 / S/PDIF; polarity-insensitive"),
    ("rz", "Bipolar RZ", "1 = +V for the first half, 0 = -V for the first half; back to 0 V in the second half.",
     "ARINC 429 (+/-10 V); self-clocking"),
    ("ami", "AMI (alternate mark inversion)", "0 = no pulse, 1 = a pulse of alternating polarity.",
     "T1 / E1 lines (B8ZS / HDB3 replace long zero runs); no DC"),
    ("mlt3", "MLT-3", "1 = step to the next level in the cycle 0, +1, 0, -1; 0 = stay.",
     "100BASE-TX after 4B5B + scrambling; low spectrum"),
    ("fsk", "FSK (Bell 202)", "1 = 1200 Hz, 0 = 2200 Hz, continuous phase, 1200 bit/s.",
     "HART on 4-20 mA loops; ACARS: MSK 1200 / 2400 Hz"),
]

# -------------------------------------------------------------------- glossary
GLOSSARY = [
    ("ACK / NACK", "Acknowledgement: the receiver confirms a frame (ACK) or rejects it (NACK). CAN uses an ACK slot that every node fills in; I2C acknowledges every byte."),
    ("ADR", "Adaptive data rate (LoRaWAN): the network server tells a node which spreading factor and power to use, based on received signal quality."),
    ("Arbitration", "Deciding who may transmit when several want to. CAN, J1850 and I2C arbitrate bit by bit: a dominant bit overwrites a recessive one and the loser backs off without damaging the frame."),
    ("ASDU", "Application Service Data Unit (IEC 60870-5): type ID, cause of transmission, common address and information objects."),
    ("BAG", "Bandwidth Allocation Gap (AFDX): the minimum time between two frames on one virtual link. Switches police it."),
    ("BAM", "Broadcast Announce Message (J1939 transport protocol): announces a multi-packet broadcast; the data packets follow without handshake."),
    ("Baud", "Symbols per second. Equal to bit/s only when every symbol carries one bit."),
    ("Bit stuffing", "Inserting an extra opposite bit after a run of equal bits (5 in CAN and HDLC, 6 ones in USB) so receivers can resynchronise and data cannot imitate a flag."),
    ("BNR", "Binary (two's complement) data format of ARINC 429, as opposed to BCD and discrete words."),
    ("Bus-off", "CAN fault confinement: a node whose transmit error counter exceeds 255 disconnects itself from the bus."),
    ("Checksum", "A simple error-detecting value: sum, XOR or LRC of the bytes. Weaker than a CRC."),
    ("Class (DNP3)", "Data class: 0 = static values, 1-3 = events by priority. Event polls read classes 1-3."),
    ("Client / server", "Modern name for master / slave in Modbus and many others: the client asks, the server answers."),
    ("COB-ID", "Communication object identifier (CANopen): the CAN identifier, a function code plus the node-ID."),
    ("COV", "Change of value (BACnet): a subscriber is notified when a value changes by more than its increment."),
    ("CPR", "Compact Position Reporting (ADS-B): latitude and longitude in 17 bits each, decoded from an even / odd pair or a reference position."),
    ("CRC", "Cyclic redundancy check: the remainder of a polynomial division over the frame, appended by the sender and checked by the receiver. Catches all burst errors up to its width."),
    ("CSMA/CA, /CD, /CR", "Carrier sense multiple access with collision avoidance (Wi-Fi), detection (classic Ethernet) or resolution (bit-wise arbitration: CAN, J1850)."),
    ("Differential signalling", "Sending a signal as the voltage difference between two wires (RS-485, CAN, LVDS). Noise coupled into both wires cancels."),
    ("DPT", "Datapoint type (KNX): how the bits of a group object are interpreted, e.g. DPT 9.001 = temperature as a 2-byte float."),
    ("DTC", "Diagnostic trouble code, e.g. P0301. Pending when first detected, confirmed after it repeats."),
    ("Duplex", "Full duplex: both directions at once (RS-422, switched Ethernet). Half duplex: one direction at a time on a shared medium (RS-485, CAN)."),
    ("Encapsulation", "Each layer wraps the data of the layer above in its own header (and trailer): an HTTP request inside TCP inside IP inside Ethernet."),
    ("Endianness", "Byte order of multi-byte values. Big-endian (network order) sends the most significant byte first; Modbus registers are big-endian but the word order of 32-bit values varies."),
    ("Error frame", "CAN: a node that detects an error destroys the frame with six dominant bits; the sender retransmits."),
    ("Fast packet", "NMEA 2000 method for messages up to 223 bytes: a sequence of CAN frames with a frame counter, no handshake."),
    ("FCS", "Frame check sequence: the CRC at the end of a frame (Ethernet, HDLC)."),
    ("Fieldbus", "A digital network that replaces point-to-point wiring between controllers and field devices."),
    ("Flow control", "Stopping a sender that is too fast for the receiver: RTS/CTS, XON/XOFF, TCP's receive window, ISO-TP's flow control frame."),
    ("Framing error", "A UART receiver found 0 where the stop bit should be: wrong baud rate, inverted line or noise."),
    ("FSK", "Frequency shift keying: bits as two frequencies (HART: 1200 / 2200 Hz)."),
    ("GOOSE", "Generic Object Oriented Substation Event (IEC 61850): fast multicast status message, repeated in a burst after each change."),
    ("HDLC", "High-level data link control: flags 0x7E, bit stuffing, address, control and CRC-16 FCS. Ancestor of many link layers."),
    ("Heartbeat", "A periodic 'I am alive' message (CANopen, MQTT keep-alive, GOOSE). Its absence is detected by a timeout."),
    ("IIN", "Internal indications (DNP3): two status bytes in every response, e.g. DEVICE_RESTART, NEED_TIME, events available."),
    ("Keep-alive", "Traffic sent only to prove a connection is still alive (MQTT PINGREQ, TCP keep-alive, UDS TesterPresent)."),
    ("LEN", "Load equivalency number (NMEA 2000): 1 LEN = 50 mA drawn from the network."),
    ("Line code", "How bits become signal levels on the wire: NRZ, Manchester, MLT-3, bipolar RZ ... See LINE CODES."),
    ("Manchester", "A line code with a transition in the middle of every bit: self-clocking and DC-free."),
    ("MBAP", "Modbus application protocol header for TCP: transaction ID, protocol ID, length and unit ID."),
    ("MMS", "Manufacturing Message Specification (ISO 9506): client / server services used by IEC 61850 over TCP 102."),
    ("MTU", "Maximum transmission unit: the largest packet a link carries (1500 bytes on Ethernet)."),
    ("Multicast", "One sender, a group of receivers: GOOSE, PROFINET DCP, IEC 61162-450, IP multicast with IGMP."),
    ("NAME (J1939)", "64-bit identity used in address claim. When two ECUs claim the same address, the lower NAME wins."),
    ("NMT", "Network management (CANopen): start, stop, pre-operational and reset commands from the NMT master."),
    ("NRC", "Negative response code (UDS): 0x7F, the service ID and the reason, e.g. 0x35 invalid key."),
    ("NRZ", "Non-return-to-zero: the level holds for the whole bit. Needs stuffing or scrambling to keep receivers in step."),
    ("Object dictionary", "The table of numbered parameters of a CANopen device (index + sub-index). Similar ideas: BACnet objects, COSEM objects, OPC UA nodes."),
    ("OBIS code", "Object identification system (DLMS/COSEM): six numbers naming a metered quantity, e.g. 1.0.1.8.0.255 = active energy import."),
    ("Parity", "One extra bit making the number of 1s even or odd. Detects any single-bit error, but no even number of errors."),
    ("PDO / SDO", "CANopen process data objects (fast, cyclic, no confirmation) and service data objects (confirmed access to the object dictionary)."),
    ("PGN / SPN", "J1939 parameter group number (which message) and suspect parameter number (which signal in it)."),
    ("Polling", "A master asks each slave in turn; slaves never talk unasked. Deterministic, but the master is a single point of failure."),
    ("Priority array", "BACnet: 16 slots for commands to one output; the highest-priority non-NULL slot wins. Relinquish = write NULL."),
    ("Publish / subscribe", "Senders publish to a topic or group; whoever subscribed receives. MQTT, DDS, GOOSE, KNX group addresses."),
    ("QoS", "Quality of service: delivery guarantees (MQTT 0/1/2) or traffic priority (VLAN priority, DDS policies)."),
    ("Reflection", "Part of a signal bouncing back from an impedance change (open end, missing terminator, stub). Seen as ringing on the scope."),
    ("Retained message", "MQTT: the broker keeps the last message of a topic and hands it to new subscribers at once."),
    ("RPI", "Requested packet interval (EtherNet/IP): how often cyclic I/O is produced."),
    ("RTU", "Remote terminal unit (SCADA), or the binary Modbus serial framing (Modbus RTU)."),
    ("Segmentation", "Splitting a message that is too long for one frame: ISO-TP, J1939 TP, TCP segments, BACnet segmentation."),
    ("SOTDMA", "Self-organising TDMA (AIS): stations announce which future slots they will use, so they can share a channel without a master."),
    ("SSM", "Sign / status matrix (ARINC 429): 2 bits telling whether the data is normal, a failure warning, no computed data or a test."),
    ("Stub", "A branch from the main bus to a device. Long stubs cause reflections; the bus specifications limit their length."),
    ("TDMA", "Time division multiple access: each node owns fixed time slots (FlexRay static segment, TTP, WirelessHART)."),
    ("Termination", "A resistor equal to the cable's characteristic impedance at each end of a bus (120 ohm for CAN and RS-485), so signals are absorbed instead of reflected."),
    ("Token passing", "The right to send passes from node to node (PROFIBUS masters, BACnet MS/TP, ControlNet)."),
    ("TTL", "Time to live / hop limit: decremented by each router; at 0 the packet is dropped and ICMP time exceeded is sent back."),
    ("Twisted pair", "Two wires twisted together so that external fields induce equal voltages in both: essential for differential buses."),
    ("Unit load", "RS-485 measure of receiver input loading; a standard driver can drive 32 unit loads."),
    ("VLAN", "IEEE 802.1Q virtual LAN tag: 12-bit VLAN ID plus a 3-bit priority used by real-time Ethernet protocols."),
    ("Watchdog", "A timer that triggers a safe reaction if a message or a heartbeat does not arrive in time."),
    ("Word order", "Order of the two 16-bit registers of a 32-bit value. 'Big-endian, word-swapped' meters are a classic Modbus trap."),
]
